@Service
public class ATMService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public ATMService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ATMEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ATMRepository.class) );
		this.validator		= applicationContext.getBean(ATMValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ATM
	 */
		public ATM createATM( CreateATMCommand command ) {

		ATM entity = new ATM();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setATMId( command.getATMId() );
            entity.setTerminalId( command.getTerminalId() );
            entity.setLocation( command.getLocation() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ATM {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateATMCommand
	 * @return		ATM
	 */
	public ATM updateATM( UpdateATMCommand command ) {

		ATM entity = new ATM();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setATMId( command.getATMId() );
            entity.setTerminalId( command.getTerminalId() );
            entity.setLocation( command.getLocation() );
            entity.setBranch( command.getBranch() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of ATM {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteATMCommand
	 */
	public void delete( DeleteATMCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getATMId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of ATM {0} ", id );

	}

	/**
	 * Method to retrieve the ATM via ATMFetchOneSummary
	 * @param 	summary ATMFetchOneSummary
	 * @return 	ATMFetchOneResponse
	 */
	public ATM getATM( ATMFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ATMFetchOneSummary arg cannot be null" );

		ATM entity = null;
		UUID id = summary.getATMId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ATM using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all ATMs
	 *
	 * @return 	List<ATM>
	 */
    public List<ATM> getAllATM() {
		List<ATM> list = projector.findAll( new FindAllATMQuery() );
		return list;
	}

	/**
	 * assign Branch on ATM
	 * @param		command AssignBranchToATMCommand
	 */
	public void assignBranch( AssignBranchToATMCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignBranch(command.getATMId(), command.getAssignment());

	}

	/**
	 * unAssign Branch on ATM
	 * @param		command UnAssignBranchFromATMCommand
	 */
	public void unAssignBranch( UnAssignBranchFromATMCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignBranch(command.getATMId());
	}
	




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final ATMEntityProjector projector;
	private final ATMValidator validator;
	private ATM aTM 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(ATMService.class);
}
